struct Extremum {
    bool high;
    double mu, height;
    int minute = 0;
    std::string label;
};
double prediction(const Model &model, double time) {
    double out = model.coefficients[0];
    for (int k = 0; k < int(model.speeds.size()); ++k) {
        double theta = angle(model.speeds[k], time);
        out += model.coefficients[2 * k + 1] * std::cos(theta) +
               model.coefficients[2 * k + 2] * std::sin(theta);
    }
    return out;
}
std::vector<Extremum> extrema(const Model &model, int start, int length, int grid) {
    int count = length * 60 / grid;
    Vector values(count + 1);
    for (int j = 0; j <= count; ++j)
        values[j] = prediction(model, double(60 * start + j * grid) / 60);
    std::vector<Extremum> out;
    for (int j = 1; j < count; ++j) {
        bool high = values[j - 1] < values[j] && values[j] > values[j + 1],
             low = values[j - 1] > values[j] && values[j] < values[j + 1];
        if (!high && !low)
            continue;
        double delta = (values[j - 1] - values[j + 1]) /
                       (2 * (values[j - 1] - 2 * values[j] + values[j + 1])),
               mu = 60 * start + j * grid + delta * grid,
               height = values[j] - (values[j - 1] - values[j + 1]) * delta / 4;
        out.push_back({high, mu, height, 0, {}});
    }
    return out;
    for (int i = 0; i <= p.length; ++i)
        s.hourly.push_back(prediction(s.model, p.start + i));
    s.waters = extrema(s.model, p.start, p.length, p.grid);
    while (s.waters.size() >= 2) {
        int first = 0;
        double minimum = std::abs(s.waters[0].height - s.waters[1].height);
        for (int i = 1; i + 1 < int(s.waters.size()); ++i) {
            double difference = std::abs(s.waters[i].height - s.waters[i + 1].height);
            if (difference < minimum) {
                minimum = difference;
                first = i;
            }
        }
        if (minimum >= p.min_range)
            break;
        s.waters.erase(s.waters.begin() + first, s.waters.begin() + first + 2);
    }
    for (Extremum &water : s.waters)
        water.minute = int(std::floor(water.mu + 0.5));
    for (int i = 0; i < int(s.waters.size()); ++i) {
        const Extremum &water = s.waters[i];
        line(s.extremes, datetime(water.minute, p.epoch_day), " ", water.label, " ",
             real(water.height, 3),
             " change=", i ? real(water.height - s.waters[i - 1].height, 3) : "none");
